def compute(vars):
    v1 = vars["v1"]  # 2018 stock-based compensation adjustment
    v2 = vars["v2"]  # 2019 stock-based compensation adjustment
    change = v2 - v1

    return {
        "value": change,
        "trace": {
            "v1": v1,
            "v2": v2,
            "change": change,
            "output_meta": {
                "currency": "USD",
                "scale": "thousand",
                "unit": None
            }
        }
    }
